CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions;
CREATE TABLE public.usuarios_autorizados (email text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT email_canonico CHECK(email=lower(trim(email))));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.usuarios_autorizados TO authenticated; GRANT ALL ON public.usuarios_autorizados TO service_role;
ALTER TABLE public.usuarios_autorizados ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_authorized() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.usuarios_autorizados a JOIN auth.users u ON lower(trim(u.email))=a.email WHERE u.id=auth.uid()); $$;
REVOKE ALL ON FUNCTION public.is_authorized() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_authorized() TO authenticated,service_role;
CREATE POLICY usuarios_autorizados_acesso ON public.usuarios_autorizados FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE FUNCTION public.validar_cadastro_autorizado() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.usuarios_autorizados WHERE email=lower(trim(NEW.email))) THEN RAISE EXCEPTION 'E-mail não autorizado para cadastro'; END IF; RETURN NEW; END $$;
CREATE TRIGGER gal_validar_cadastro BEFORE INSERT OR UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.validar_cadastro_autorizado();
CREATE FUNCTION public.normalizar_texto(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT trim(regexp_replace(regexp_replace(lower(extensions.unaccent(t)), '[^a-z0-9 ]','','g'), ' +',' ','g')); $$;
CREATE FUNCTION public.so_digitos(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT nullif(regexp_replace(t,'[^0-9]','','g'),''); $$;
CREATE FUNCTION public.hoje_sp() RETURNS date LANGUAGE sql STABLE SET search_path=public AS $$ SELECT (now() AT TIME ZONE 'America/Sao_Paulo')::date; $$;
CREATE FUNCTION public.whatsapp_normalizado(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN length(public.so_digitos(t)) IN (10,11) THEN '55'||public.so_digitos(t) ELSE public.so_digitos(t) END; $$;
CREATE TYPE public.situacao_prado AS ENUM('nao_verificado','livre','atendida_outro_rep');
CREATE TYPE public.linha_marca AS ENUM('esquadrias','kit_porta','outra');
CREATE TYPE public.etapa_comercial AS ENUM('prospeccao','aguardando_demanda','demanda_prevista','orcamento','negociacao','fechado','perdido');
CREATE TYPE public.tipo_lote AS ENUM('contramarco','apto_modelo','andar_tipo','area_comum','especiais','reposicao');
CREATE TYPE public.status_lote AS ENUM('aguardando_cadastro','aguardando_medicao','medicao_agendada','medido','pcp','em_producao','produzido','entregue');
CREATE TYPE public.tipo_registro AS ENUM('nota','ata','cronograma','medicao','ligacao','whatsapp','email','visita','problema');
CREATE TYPE public.direcao_registro AS ENUM('enviado','recebido','nenhuma');
CREATE TYPE public.origem_followup AS ENUM('prospeccao','obra','automatico','manual');
CREATE TYPE public.status_followup AS ENUM('pendente','concluido','cancelado');
CREATE TABLE public.marcas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text NOT NULL UNIQUE,linha public.linha_marca NOT NULL,cor text,ativa boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.marcas TO authenticated; GRANT ALL ON public.marcas TO service_role; ALTER TABLE public.marcas ENABLE ROW LEVEL SECURITY; CREATE POLICY marcas_acesso ON public.marcas FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE TABLE public.clientes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text NOT NULL,nome_normalizado text NOT NULL UNIQUE,cnpj text,cidade text,uf text,situacao_prado public.situacao_prado NOT NULL DEFAULT 'nao_verificado',representante_prado text,observacoes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clientes TO authenticated; GRANT ALL ON public.clientes TO service_role; ALTER TABLE public.clientes ENABLE ROW LEVEL SECURITY; CREATE POLICY clientes_acesso ON public.clientes FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE UNIQUE INDEX clientes_cnpj_unico ON public.clientes(cnpj) WHERE cnpj IS NOT NULL; CREATE INDEX clientes_nome_busca ON public.clientes USING gin(nome_normalizado extensions.gin_trgm_ops);
CREATE TABLE public.contatos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cliente_id uuid REFERENCES public.clientes(id),nome text NOT NULL,cargo text,whatsapp text,email text,tentativas_sem_resposta int NOT NULL DEFAULT 0 CHECK(tentativas_sem_resposta>=0),observacoes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contatos TO authenticated; GRANT ALL ON public.contatos TO service_role; ALTER TABLE public.contatos ENABLE ROW LEVEL SECURITY; CREATE POLICY contatos_acesso ON public.contatos FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE UNIQUE INDEX contatos_whatsapp_unico ON public.contatos(whatsapp) WHERE whatsapp IS NOT NULL; CREATE UNIQUE INDEX contatos_email_unico ON public.contatos(email) WHERE email IS NOT NULL;
CREATE TABLE public.oportunidades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cliente_id uuid NOT NULL REFERENCES public.clientes(id),contato_id uuid REFERENCES public.contatos(id),marca_ids uuid[] NOT NULL,descricao text,etapa public.etapa_comercial NOT NULL DEFAULT 'prospeccao',necessidade_prevista date,obra_id uuid,observacoes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.oportunidades TO authenticated; GRANT ALL ON public.oportunidades TO service_role; ALTER TABLE public.oportunidades ENABLE ROW LEVEL SECURITY; CREATE POLICY oportunidades_acesso ON public.oportunidades FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE TABLE public.obras(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cliente_id uuid NOT NULL REFERENCES public.clientes(id),oportunidade_id uuid REFERENCES public.oportunidades(id),nome text NOT NULL,cidade text,data_fechamento date,finalizada_em date,problema_ativo boolean NOT NULL DEFAULT false,problema_texto text,observacoes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.obras TO authenticated; GRANT ALL ON public.obras TO service_role; ALTER TABLE public.obras ENABLE ROW LEVEL SECURITY; CREATE POLICY obras_acesso ON public.obras FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
ALTER TABLE public.oportunidades ADD CONSTRAINT oportunidades_obra_fk FOREIGN KEY(obra_id) REFERENCES public.obras(id);
CREATE TABLE public.lotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),obra_id uuid NOT NULL REFERENCES public.obras(id),tipo public.tipo_lote NOT NULL,descricao text,quantidade int CHECK(quantidade>=0),status public.status_lote NOT NULL DEFAULT 'aguardando_cadastro',cadastro_completo boolean NOT NULL DEFAULT false,previsao_medicao date,medido_em date,prazo_dias int CHECK(prazo_dias>=0),acrescimo_ferias_dias int NOT NULL DEFAULT 0,ferias_pendente boolean NOT NULL DEFAULT false,previsao_entrega date,data_confirmada date,recebimento_confirmado boolean NOT NULL DEFAULT false,responsavel_recebimento text,entregue_em date,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT lotes_cadastro_medicao CHECK(cadastro_completo OR (previsao_medicao IS NULL AND medido_em IS NULL)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.lotes TO authenticated; GRANT ALL ON public.lotes TO service_role; ALTER TABLE public.lotes ENABLE ROW LEVEL SECURITY; CREATE POLICY lotes_acesso ON public.lotes FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE TABLE public.checklist_itens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),obra_id uuid NOT NULL REFERENCES public.obras(id),ordem int NOT NULL,item text NOT NULL,feito boolean NOT NULL DEFAULT false,feito_em date,nota text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(obra_id,ordem));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.checklist_itens TO authenticated; GRANT ALL ON public.checklist_itens TO service_role; ALTER TABLE public.checklist_itens ENABLE ROW LEVEL SECURITY; CREATE POLICY checklist_itens_acesso ON public.checklist_itens FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE TABLE public.registros(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),obra_id uuid REFERENCES public.obras(id),oportunidade_id uuid REFERENCES public.oportunidades(id),cliente_id uuid REFERENCES public.clientes(id),contato_id uuid REFERENCES public.contatos(id),lote_id uuid REFERENCES public.lotes(id),tipo public.tipo_registro NOT NULL,direcao public.direcao_registro NOT NULL DEFAULT 'nenhuma',texto text,data timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT registros_vinculo CHECK(num_nonnulls(obra_id,oportunidade_id,cliente_id,contato_id)>=1));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.registros TO authenticated; GRANT ALL ON public.registros TO service_role; ALTER TABLE public.registros ENABLE ROW LEVEL SECURITY; CREATE POLICY registros_acesso ON public.registros FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE TABLE public.arquivos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),registro_id uuid REFERENCES public.registros(id),lote_id uuid REFERENCES public.lotes(id),obra_id uuid REFERENCES public.obras(id),nome text NOT NULL,mime text,tamanho bigint CHECK(tamanho>=0),caminho text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.arquivos TO authenticated; GRANT ALL ON public.arquivos TO service_role; ALTER TABLE public.arquivos ENABLE ROW LEVEL SECURITY; CREATE POLICY arquivos_acesso ON public.arquivos FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE TABLE public.followups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),obra_id uuid REFERENCES public.obras(id),oportunidade_id uuid REFERENCES public.oportunidades(id),cliente_id uuid REFERENCES public.clientes(id),contato_id uuid REFERENCES public.contatos(id),lote_id uuid REFERENCES public.lotes(id),data date NOT NULL,motivo text NOT NULL,origem public.origem_followup NOT NULL,status public.status_followup NOT NULL DEFAULT 'pendente',tentativa int,concluido_em timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.followups TO authenticated; GRANT ALL ON public.followups TO service_role; ALTER TABLE public.followups ENABLE ROW LEVEL SECURITY; CREATE POLICY followups_acesso ON public.followups FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE UNIQUE INDEX followups_prospeccao_pendente ON public.followups(contato_id) WHERE status='pendente' AND origem='prospeccao'; CREATE INDEX followups_data_status ON public.followups(status,data);
CREATE TABLE public.configuracoes(id int PRIMARY KEY DEFAULT 1 CHECK(id=1),prazos jsonb NOT NULL DEFAULT '{"contramarco":30,"apto_modelo":45,"andar_tipo":70,"area_comum":120,"especiais":130,"reposicao":45}',ferias_inicio date,ferias_fim date,acrescimo_ferias_dias int NOT NULL DEFAULT 25 CHECK(acrescimo_ferias_dias>=0),revisao_dias int NOT NULL DEFAULT 40 CHECK(revisao_dias>=0),dias_tarefa_inicial int NOT NULL DEFAULT 2 CHECK(dias_tarefa_inicial>=0),alerta_entrega_dias int NOT NULL DEFAULT 7 CHECK(alerta_entrega_dias>=0),demanda_antecedencia_dias int NOT NULL DEFAULT 60 CHECK(demanda_antecedencia_dias>=0),cadencia_intervalos int[] NOT NULL DEFAULT '{5,7}',cadencia_max_tentativas int NOT NULL DEFAULT 3 CHECK(cadencia_max_tentativas>=1),cadencia_pausa_dias int NOT NULL DEFAULT 60 CHECK(cadencia_pausa_dias>=0),retomar_sem_demanda_dias int NOT NULL DEFAULT 60 CHECK(retomar_sem_demanda_dias>=0),atalhos_dias int[] NOT NULL DEFAULT '{3,7,15,30}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.configuracoes TO authenticated; GRANT ALL ON public.configuracoes TO service_role; ALTER TABLE public.configuracoes ENABLE ROW LEVEL SECURITY; CREATE POLICY configuracoes_acesso ON public.configuracoes FOR ALL TO authenticated USING(public.is_authorized()) WITH CHECK(public.is_authorized());
CREATE FUNCTION public.atualizar_timestamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE FUNCTION public.normalizar_cliente() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.nome_normalizado=public.normalizar_texto(NEW.nome); IF NEW.nome_normalizado='' THEN RAISE EXCEPTION 'Nome de cliente inválido'; END IF; NEW.cnpj=public.so_digitos(NEW.cnpj); RETURN NEW; END $$;
CREATE TRIGGER clientes_normalizar BEFORE INSERT OR UPDATE ON public.clientes FOR EACH ROW EXECUTE FUNCTION public.normalizar_cliente();
CREATE FUNCTION public.normalizar_contato() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.whatsapp=public.whatsapp_normalizado(NEW.whatsapp); NEW.email=nullif(lower(trim(NEW.email)),''); RETURN NEW; END $$;
CREATE TRIGGER contatos_normalizar BEFORE INSERT OR UPDATE ON public.contatos FOR EACH ROW EXECUTE FUNCTION public.normalizar_contato();
CREATE FUNCTION public.validar_oportunidade() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF coalesce(cardinality(NEW.marca_ids),0)<1 OR EXISTS(SELECT 1 FROM unnest(NEW.marca_ids) x WHERE x IS NULL OR NOT EXISTS(SELECT 1 FROM public.marcas m WHERE m.id=x)) THEN RAISE EXCEPTION 'Informe pelo menos uma marca válida'; END IF; IF NEW.necessidade_prevista IS NOT NULL THEN NEW.necessidade_prevista=date_trunc('month',NEW.necessidade_prevista)::date; END IF; RETURN NEW; END $$;
CREATE TRIGGER oportunidades_validar BEFORE INSERT OR UPDATE ON public.oportunidades FOR EACH ROW EXECUTE FUNCTION public.validar_oportunidade();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['usuarios_autorizados','marcas','clientes','contatos','oportunidades','obras','lotes','checklist_itens','registros','arquivos','followups','configuracoes'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.atualizar_timestamp()',t||'_timestamp',t); EXECUTE format('REVOKE ALL ON public.%I FROM anon',t); END LOOP; END $$;
INSERT INTO public.marcas(nome,linha) VALUES('PRADO','esquadrias'),('Scalla','esquadrias'),('Rohden','kit_porta'),('Imab','kit_porta'); INSERT INTO public.configuracoes(id) VALUES(1);
REVOKE ALL ON FUNCTION public.validar_cadastro_autorizado(),public.normalizar_texto(text),public.so_digitos(text),public.hoje_sp(),public.whatsapp_normalizado(text),public.atualizar_timestamp(),public.normalizar_cliente(),public.normalizar_contato(),public.validar_oportunidade() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.normalizar_texto(text),public.so_digitos(text),public.hoje_sp(),public.whatsapp_normalizado(text) TO authenticated,service_role;